import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"JD11 蛇形矩阵","description":"简单 通过率：47.15% 时间限制：1秒 空间限制：32M 知识点 数组 描述 蛇形矩阵是由1开始的自然数依次排列成的一个矩阵上三角形。 例如，当输入5时，应该输出的三角形为： 1 3 6 10 15 2 5 9 14 4 8 13 7 12 11 输入描述： 输入正整数N（N。","frontmatter":{"title":"JD11 蛇形矩阵","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：47.15% 时间限制：1秒 空间限制：32M 知识点 数组 描述 蛇形矩阵是由1开始的自然数依次排列成的一个矩阵上三角形。 例如，当输入5时，应该输出的三角形为： 1 3 6 10 15 2 5 9 14 4 8 13 7 12 11 输入描述： 输入正整数N（N。","sidebarWeight":73,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD11 蛇形矩阵.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD11 蛇形矩阵.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD11 蛇形矩阵.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD11 蛇形矩阵.md"};function o(l,a,s,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<div><h1 id="jd11-蛇形矩阵" tabindex="-1">JD11 蛇形矩阵 <a class="header-anchor" href="#jd11-蛇形矩阵" aria-label="Permalink to &quot;JD11 蛇形矩阵&quot;">​</a></h1><blockquote><p>本节目标：理解“JD11 蛇形矩阵”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：47.15% 时间限制：1秒 空间限制：32M 知识点==数组== <strong>描述</strong> 蛇形矩阵是由1开始的自然数依次排列成的一个矩阵上三角形。 例如，当输入5时，应该输出的三角形为： 1 3 6 10 15 2 5 9 14 4 8 13 7 12 11</p></blockquote><p><strong>输入描述：</strong> 输入正整数N（N不大于100） <strong>输出描述：</strong> 输出一个N行的蛇形矩阵。 <strong>示例1</strong> 输入： 4 ==复制== 输出： 1 3 6 102 5 94 87</p><ul><li>从输出看，基本确定是一个双层循环</li><li>由于数量递减，第二个循环的最大值是要减去当前第一个循环的索引的</li><li>第二个循环的值即和当前循环的索引有关，又和第一个索引的值有关</li><li>要找到这个规律</li><li>选取适当的range，为了简化运算，可以从1开始，结束也相应加1</li><li>每一行的第一个数字，等于它前一行的数字+行索引：1，2，4，7，11，因此可以用一个变量记录之前的值，然后加上索引，一行的计算完成后，更新这个记录上一行值的变量。</li><li>确定第一行第一个数字后，我们发现，每一列第二个数字都是前一个数字加上当前的行号和列号；</li></ul><p>直接计算每一行第一个数字，然后基于第一个数字来计算后面的数字，这样可以使逻辑更加直观一些。</p><p>基于这个规律，我们可以写出如下的代码： def print_snake_matrix(n):</p><h1 id="初始化第一个数字为1" tabindex="-1">初始化第一个数字为1 <a class="header-anchor" href="#初始化第一个数字为1" aria-label="Permalink to &quot;初始化第一个数字为1&quot;">​</a></h1><p>start = 1 for i in range(1, n + 1):</p><h1 id="打印每一行的第一个数字" tabindex="-1">打印每一行的第一个数字 <a class="header-anchor" href="#打印每一行的第一个数字" aria-label="Permalink to &quot;打印每一行的第一个数字&quot;">​</a></h1><p>num = start print(num, end=&#39;&#39;)</p><h1 id="计算并打印当前行的其余数字" tabindex="-1">计算并打印当前行的其余数字 <a class="header-anchor" href="#计算并打印当前行的其余数字" aria-label="Permalink to &quot;计算并打印当前行的其余数字&quot;">​</a></h1><p>for j in range(1, n - i + 1): num += i + j print(&#39; {}&#39;.format(num), end=&#39;&#39;)</p><h1 id="换行准备打印下一行" tabindex="-1">换行准备打印下一行 <a class="header-anchor" href="#换行准备打印下一行" aria-label="Permalink to &quot;换行准备打印下一行&quot;">​</a></h1><p>print()</p><h1 id="更新下一行的起始数字" tabindex="-1">更新下一行的起始数字 <a class="header-anchor" href="#更新下一行的起始数字" aria-label="Permalink to &quot;更新下一行的起始数字&quot;">​</a></h1><p>start += i</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="执行函数" tabindex="-1">执行函数 <a class="header-anchor" href="#执行函数" aria-label="Permalink to &quot;执行函数&quot;">​</a></h1><p>print_snake_matrix(n)</p><p>这个方法首先计算每一行的起始数字，然后基于起始数字和行号、列号的关系计算出每一行的其他数字，并逐行打印。通过更新每行的起始数字来为打印下一行做准备。这样做可以让整个过程更加直观，同时也避免了对每个数字进行独立计算。</p></div>',1)])])}const _=e(n,[["render",o]]);export{u as __pageData,_ as default};
